(function() {
  var fm, url;

  fm = function(amount, precision) {
    return accounting.formatMoney(amount, {
      symbol: "€",
      thousand: Lang.thousandFormat,
      decimal: Lang.decimalFormat,
      format: Lang.moneyFormat,
      precision: precision
    });
  };

  url = "https://api.pioupiou.fr/v1/shop/invoice" + document.location.search;

  $.getJSON(url, function(order) {
    var paymentMethod, taxIndex, totalTaxExc, totalTaxInc;
    if (!order) {
      $('.alert-warning').removeClass("hidden");
      return;
    }
    if (order.error) {
      $('.alert-danger').removeClass("hidden");
      return;
    }
    if (!(order.invoicing && order.invoicing.id)) {
      $('.alert-warning').removeClass("hidden");
      return;
    }
    $('.id').text(order.invoicing.id);
    $('.date').text(order.invoicing.date);
    $('.company').text(order.invoicing.company);
    $('.name').text(order.invoicing.name);
    $('.address1').text(order.invoicing.address1);
    $('.address2').text(order.invoicing.address2);
    $('.postcode').text(order.invoicing.postcode);
    $('.city').text(order.invoicing.city);
    $('.country').text(order.invoicing.country);
    $('.vat_number').text(order.invoicing.vat_number);
    taxIndex = null;
    totalTaxExc = 0;
    order.items.ref.forEach(function(ref, i) {
      var row, totalLine;
      if (ref === "tax") {
        return taxIndex = i;
      }
      row = $("<tr></tr>");
      row.append($("<td></td>").text(order.items.desc[i]));
      row.append($("<td></td>").addClass("text-right").text(order.items.quantity[i]));
      row.append($("<td></td>").addClass("text-right").text(fm(order.items.price[i], 2)));
      totalLine = order.items.price[i] * order.items.quantity[i];
      row.append($("<td></td>").addClass("text-right").text(fm(totalLine, 2)));
      totalTaxExc += totalLine;
      return $(".invoice-content").append(row);
    });
    $('.totalTaxExc').text(fm(totalTaxExc, 2));
    if (taxIndex) {
      totalTaxInc = totalTaxExc + order.items.price[taxIndex];
      $('.totalTax').text(fm(order.items.price[taxIndex], 2));
      $('.taxDesc').text(order.items.desc[taxIndex]);
      $('.totalTaxInc').text(fm(totalTaxInc, 2));
    } else {
      $(".has-tax").hide();
    }
    $('.paymentAmount').text(fm(order.payment.amount, 2));
    paymentMethod = order.payment.method;
    if (Lang.paymentMethod[order.payment.method]) {
      paymentMethod = Lang.paymentMethod[order.payment.method];
    }
    $('.paymentMethod').text(paymentMethod);
    $('.paymentDate').text(order.payment.date);
    $('.paymentId').text(order.payment.id);
    $('.invoice').removeClass("hidden");
    return window.print();
  }).always(function() {
    return $('.alert-info').hide();
  }).fail(function() {
    return $('.alert-danger').removeClass("hidden");
  });

}).call(this);

